const $=s=>document.querySelector(s),C=CloudCore,CONFIG_KEY='build-intelligence-firebase-config-v1';
let app,auth,db,A,F,App,unsub,user=null,busy=false;
function message(text,type=''){const e=$('#status');e.textContent=text;e.className='status '+type}
function buttons(){const connected=!!auth;$('#connect').disabled=busy||connected;$('#config').disabled=busy||connected;$('#remember').disabled=busy||connected;$('#disconnect').disabled=busy||!connected;$('#login').disabled=busy||!connected||!!user;$('#signup').disabled=busy||!connected||!!user;$('#logout').disabled=busy||!user;document.querySelectorAll('[data-save],[data-load],[data-read]').forEach(b=>b.disabled=busy||!user)}
const errors={};
Object.assign(errors,{'auth/invalid-credential':'이메일 또는 비밀번호를 확인하세요.','auth/email-already-in-use':'이미 등록된 이메일입니다. 로그인하세요.','auth/operation-not-allowed':'Firebase 콘솔에서 이메일/비밀번호 로그인을 사용 설정하세요.','auth/unauthorized-domain':'Firebase Authentication의 승인된 도메인에 이 사이트 주소를 추가하세요.','auth/weak-password':'프로젝트 비밀번호 정책에 맞는 비밀번호를 입력하세요.','auth/invalid-api-key':'웹 앱 apiKey를 확인하세요.','auth/network-request-failed':'네트워크 또는 API 키의 웹사이트 제한 설정을 확인하세요.','permission-denied':'Firestore 보안 규칙을 확인하세요. 로그인 사용자 본인 경로에만 접근해야 합니다.','failed-precondition':'기본 (default) Firestore 데이터베이스가 생성되었는지 확인하세요.','unavailable':'Firebase 연결이 지연되거나 오프라인입니다. 네트워크를 확인하고 다시 시도하세요.'});
async function action(fn){if(busy)return;busy=true;buttons();try{await fn()}catch(e){message(errors[e.code]||e.message||'연결 오류가 발생했습니다.','error')}finally{busy=false;buttons()}}
function local(kind){return localStorage.getItem(C.KEYS[kind])||JSON.stringify(kind==='model'?GeoEngine.seed():BuildModel.seed())}
function refreshLocal(){for(const kind of Object.keys(C.KEYS)){try{const text=local(kind),obj=C.validatePayload(kind,text,GeoEngine);$('#'+kind+'Local').textContent=(kind==='model'?`${obj.name} · ${obj.elements.length}개 구조물`:`요청 ${obj.requests.length}건 · 기록 ${obj.records.length}건`)+` · ${(new TextEncoder().encode(text).length/1000).toFixed(1)}KB` }catch(e){$('#'+kind+'Local').textContent=e.message}}}
const defaultConfig=globalThis.SPATIA_FIREBASE_CONFIG;
try{$('#config').value=defaultConfig?JSON.stringify(defaultConfig,null,2):(localStorage.getItem(CONFIG_KEY)||'')}catch{}
async function sdk(){[App,A,F]=await Promise.all([import('https://www.gstatic.com/firebasejs/13.1.0/firebase-app.js'),import('https://www.gstatic.com/firebasejs/13.1.0/firebase-auth.js'),import('https://www.gstatic.com/firebasejs/13.1.0/firebase-firestore.js')])}
async function connectProject(){const config=C.parseConfig($('#config').value);message('SPATIA Firebase SDK를 불러오는 중입니다…');await sdk();app=App.initializeApp(config,'build-intelligence');try{auth=A.getAuth(app);db=F.getFirestore(app);await A.setPersistence(auth,A.browserSessionPersistence);if($('#remember').checked)localStorage.setItem(CONFIG_KEY,JSON.stringify(config,null,2));else localStorage.removeItem(CONFIG_KEY)}catch(e){await App.deleteApp(app);app=auth=db=null;throw e}$('#projectMeta').textContent='프로젝트: '+config.projectId;unsub=A.onAuthStateChanged(auth,current=>{user=current;$('#account').textContent=current?`${current.email} · UID ${current.uid}`:'로그인 전';$('#password').value='';buttons();message(current?'로그인 완료 · 백업 확인 또는 저장을 선택하세요.':config.projectId+' 초기화 완료 · 로그인 후 Firestore 저장 권한을 확인할 수 있습니다.',current?'good':'')});message('프로젝트 설정 완료 · 로그인하세요.')}
$('#configForm').onsubmit=e=>{e.preventDefault();action(connectProject)};
$('#authForm').onsubmit=e=>{e.preventDefault();action(async()=>{await A.signInWithEmailAndPassword(auth,$('#email').value.trim(),$('#password').value);$('#password').value=''})};
$('#signup').onclick=()=>{if(!$('#authForm').reportValidity())return;action(async()=>{await A.createUserWithEmailAndPassword(auth,$('#email').value.trim(),$('#password').value);$('#password').value='';message('백업 계정 생성·로그인 완료 · 클라우드 저장을 시작할 수 있습니다.','good')})};
$('#logout').onclick=()=>action(async()=>{await A.signOut(auth);for(const k of Object.keys(C.KEYS))$('#'+k+'Remote').textContent='클라우드 상태 미확인';message('로그아웃했습니다. 이 브라우저의 모델·이력은 남아 있습니다.')});
$('#disconnect').onclick=()=>action(async()=>{if(auth)await A.signOut(auth);unsub?.();await App.deleteApp(app);app=auth=db=user=null;localStorage.removeItem(CONFIG_KEY);$('#config').value='';$('#projectMeta').textContent='설정 미등록';for(const k of Object.keys(C.KEYS))$('#'+k+'Remote').textContent='클라우드 상태 미확인';message('연결을 해제했습니다. 클라우드 데이터는 삭제하지 않았습니다.')});
function reference(kind){if(!user)throw Error('먼저 로그인하세요.');return F.doc(db,'users',user.uid,'snapshots',kind)}
function describe(kind,data){$('#'+kind+'Remote').textContent=data?`클라우드 백업 · ${data.updatedAt?.toDate?.().toLocaleString('ko-KR')||'시각 확인 중'}`:'저장된 백업이 없습니다.'}
for(const b of document.querySelectorAll('[data-read]'))b.onclick=()=>action(async()=>{message('서버에서 백업을 확인하는 중입니다…');const s=await F.getDocFromServer(reference(b.dataset.read));if(s.exists())C.validateDocument(s.data(),b.dataset.read,GeoEngine);describe(b.dataset.read,s.exists()?s.data():null);message(s.exists()?'서버의 백업을 확인했습니다.':'아직 백업이 없습니다. 현재 데이터를 저장하세요.','good')});
for(const b of document.querySelectorAll('[data-save]'))b.onclick=()=>action(async()=>{const kind=b.dataset.save,text=local(kind);C.validatePayload(kind,text,GeoEngine);if(!confirm((kind==='model'?'공간 모델':'유지관리 이력(사진·비공개 기록 포함)')+'을 로그인 계정의 클라우드에 저장할까요? 같은 종류의 기존 백업은 교체됩니다.'))return;message('Firestore에 저장하는 중입니다…');await F.setDoc(reference(kind),{schemaVersion:1,kind,payload:text,provenance:'user_workspace_snapshot',updatedAt:F.serverTimestamp()});describe(kind,{updatedAt:{toDate:()=>new Date()}});message('클라우드 저장 완료 · Firebase 서버가 저장을 확인했습니다.','good')});
for(const b of document.querySelectorAll('[data-load]'))b.onclick=()=>action(async()=>{const kind=b.dataset.load;message('서버에서 백업을 읽는 중입니다…');const s=await F.getDocFromServer(reference(kind));if(!s.exists()){describe(kind,null);message('저장된 백업이 없습니다.');return}const data=s.data(),valid=C.validateDocument(data,kind,GeoEngine);describe(kind,data);if(!confirm('이 브라우저의 '+(kind==='model'?'공간 모델':'유지관리 이력')+'을 클라우드 백업으로 교체할까요? 기존 데이터가 필요하면 먼저 분석·유지관리 화면에서 JSON으로 내보내세요.')){message('불러오기를 취소했습니다.');return}localStorage.setItem(C.KEYS[kind],JSON.stringify(valid));refreshLocal();message('불러오기 완료 · 아래의 분석·유지관리 화면을 새로 열어 확인하세요.','good')});
fetch('firestore.rules').then(r=>{if(!r.ok)throw Error();return r.text()}).then(t=>$('#rulesText').textContent=t).catch(()=>$('#rulesText').textContent='보안 규칙 다운로드 링크를 이용하세요.');
refreshLocal();buttons();window.addEventListener('storage',refreshLocal);
if(defaultConfig)action(connectProject);
